sed -i '278i\
  const handleValidateSubmit = async (report: OutbreakReport, data: any) => {\n    if (!user) return;\n    try {\n      await updateDoc(doc(db, "outbreaks", report.id!), {\n        validation: {\n          decision: data.status,\n          basis: ["Validator Review"],\n          notes: data.remarks,\n          validatorName: user.name || "IPCN Validator",\n          validatorId: user.uid,\n          validatedAt: new Date().toISOString(),\n        },\n        updatedAt: serverTimestamp()\n      });\n      setSelectedReportForValidation(null);\n      alert(`Outbreak ${data.status} successfully`);\n    } catch (error) {\n      console.error(error);\n      alert("Validation failed");\n    }\n  };\n' src/components/Outbreak.tsx
